SELECT s.name SchemaName,t.name TableName,c.name ColumnName,ty.name SqlType,c.max_length MaxLength,c.precision Precision,c.scale Scale,c.is_nullable IsNullable,c.column_id Ordinal,c.is_computed IsComputed,CONVERT(nvarchar(max),ep.value) Description,cc.definition ComputedDefinition,c.collation_name Collation FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.extended_properties ep ON ep.class=1 AND ep.major_id=t.object_id AND ep.minor_id=c.column_id AND ep.name=N'Description' LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id ORDER BY s.name,t.name,c.column_id